"""Publish only the isolated trial's evidence and frozen predictions, never human answers."""
import argparse,json,shutil,subprocess,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def e(x):return html.escape(str(x))
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--run-dir',type=Path,required=True);a=ap.parse_args();d=a.run_dir.resolve();out=ROOT/'docs/results/rubric-trial3';out.mkdir(parents=True,exist_ok=True)
 sel=json.loads((d/'selection.json').read_text());parts=[];summary=[]
 for source in sel:
  sid=source['trial_id'];dest=out/sid;dest.mkdir(exist_ok=True);r=json.loads((d/sid/'prediction.json').read_text());grade=r['overall']['grade'];summary.append({'id':sid,'original_sample':source['original_sample_number'],'grade':grade,'status':r['overall']['status'],'reason':r['overall']['reason']})
  for file in ['prediction.json','measurements.json','assignment-used.json']:shutil.copyfile(d/sid/file,dest/file)
  shutil.copyfile(d/'inputs'/sid/'frames.json',dest/'frames.json')
  for name in ['input-1.jpg','input-2.jpg','overview.jpg']:shutil.copyfile(d/'inputs'/sid/name,dest/name)
  for p in (d/sid).glob('overlay-*.jpg'):shutil.copyfile(p,dest/p.name)
  if (d/sid/'masks').exists():shutil.copytree(d/sid/'masks',dest/'masks',dirs_exist_ok=True)
  original=Path('/Users/minimax/game-video-review')/source['url']
  if original.exists():shutil.copyfile(original,dest/'original.mp4')
  if not (dest/'original.mp4').exists():raise FileNotFoundError('Provide original source clip before rendering')
  video=dest/'video.mp4'
  if not video.exists():subprocess.run(['ffmpeg','-v','error','-i',str(dest/'original.mp4'),'-vf','scale=960:-2','-c:v','libx264','-crf','27','-preset','fast','-an','-movflags','+faststart',str(video)],check=True)
  for phase in ['identify','judge']:
   call=d/'model-calls'/sid/phase;target=dest/'calls'/phase;target.mkdir(parents=True,exist_ok=True)
   for name in ['prompt.txt','schema.json','result.json']:
    shutil.copyfile(call/name,target/name)
   manifest=json.loads((call/'input-images.json').read_text())
   for item in manifest:item['path']=Path(item['path']).name
   (target/'input-images.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
   if phase=='judge':
    shutil.copyfile(call/'segmentation-contact-sheet.jpg',target/'segmentation-contact-sheet.jpg')
    shutil.copyfile(call/'validation.json',target/'validation.json')
   for img in ['input-1.jpg','input-2.jpg']:shutil.copyfile(dest/img,target/img)
   ex=json.loads((call/'execution.json').read_text());ex.pop('command',None)
   for line in (call/'events.jsonl').read_text().splitlines():
    try:ev=json.loads(line)
    except ValueError:continue
    if ev.get('type')=='turn.completed':ex['usage']=ev.get('usage')
   (target/'execution.json').write_text(json.dumps(ex,ensure_ascii=False,indent=2))
  timings={phase:json.loads((d/'model-calls'/sid/phase/'execution.json').read_text())['elapsed_seconds'] for phase in ['identify','judge']}
  qa={ (q['frame_index'],q['object_id']):q for q in r['segmentation_review']};rows=json.loads((d/sid/'measurements.json').read_text());measure=[]
  for row in rows:
   for ob in row['objects']:
    review=qa.get((row['frame_index'],ob['object_id']))
    if review:
     pos=ob.get('position',{});measure.append('<tr>'+''.join('<td>'+e(v)+'</td>' for v in [f"{row['time']:.2f}s",ob['object_id'],'采用' if review['mask_accepted'] else '拒绝',pos.get('center'),ob.get('area',{}).get('visible_ratio'),ob.get('background_separation',{}).get('color_JS_distance'),review['reason']])+'</tr>')
  checks=''.join('<tr>'+''.join('<td>'+e(c[k])+'</td>' for k in ['stage_id','checkpoint_id','indicator_id','state','time_ranges','input_evidence_ids','observation','impact','context_support','exceptions_checked'])+'</tr>' for c in r['checks'])
  stages=''.join('<li><b>'+e(s['stage_id'])+' '+e(s['time_range'])+'</b>：'+e(s['necessary_information'])+'<br>主体 '+e(s['subject_ids'])+'；陪体 '+e(s['supporting_element_ids'])+'；前景 '+e(s['foreground_ids'])+'；背景 '+e(s['background_ids'])+'<br>关键依据：'+e(s['key_stage_reason'])+'</li>' for s in r['stages'])
  overlays=''.join('<figure><img loading="lazy" src="'+sid+'/'+p.name+'"><figcaption>'+e(p.stem)+'</figcaption></figure>' for p in sorted((dest).glob('overlay-*.jpg')))
  parts.append(f'''<section class="case" id="{sid}" hidden aria-label="样本 {sid}"><div class="left-pane"><h2>{sid} · 原样本 {source['original_sample_number']} · {e(source['game'])}</h2><video controls preload="metadata" src="{sid}/video.mp4"></video><p class="muted">片内时间 0–20s · 4FPS / 80帧 · 原会话起点 {source['clip_start']:.2f}s</p><details><summary>内容提取与阶段</summary><ul>{stages}</ul></details><details><summary>实际输入的完整序列图</summary><img loading="lazy" src="{sid}/input-1.jpg"><img loading="lazy" src="{sid}/input-2.jpg"></details><details><summary>模型审查的分割覆盖图</summary><div class="gallery">{overlays}</div></details><details><summary>测量值与分割采用／拒绝记录</summary><p>中心=(x1+x2)/(2W), (y1+y2)/(2H)；可见占比=mask像素数/(W×H)。JS为主体与局部背景Lab直方图距离。数值作为证据，不是美学阈值；拒绝分割对应的数值不采用。无完整主体mask，不输出遮挡率。</p><div class="scroll"><table><tr><th>时间</th><th>对象</th><th>QA</th><th>中心</th><th>可见占比</th><th>颜色JS</th><th>原因</th></tr>{''.join(measure)}</table></div></details><p class="muted">内容识别 {timings['identify']:.1f}s · 判档 {timings['judge']:.1f}s（本次实测）</p><p><a href="{sid}/original.mp4">原始片段</a> · <a href="{sid}/measurements.json">逐帧测量JSON</a> · <a href="{sid}/assignment-used.json">对象与定位</a></p></div><aside class="right-pane"><div class="result-heading"><h2>机标结论</h2><span class="grade grade-{grade}">{e({'low':'低','middle':'中','high':'高'}.get(grade,r['overall']['status']))}</span></div><p class="conclusion">{e(r['overall']['reason'])}</p><h3>分档理由</h3><p>{e(r['overall']['adjacent_grade_explanation'])}</p><details><summary>基础条件、增强效果与不确定性</summary><p><b>基础条件：</b>{e(r['overall']['baseline_status'])}</p><p><b>关键损害：</b>{e(r['overall']['material_harm_status'])}</p><p><b>增强效果：</b>{e(r['overall']['expressive_enhancement_status'])}</p><ul>{''.join('<li>'+e(x)+'</li>' for x in r['overall']['uncertainties'])}</ul></details><p class="muted">决定性检查点：{e(r['overall']['decisive_checkpoint_ids'])}<br>事件：{e(r['overall']['decisive_event_ids'])}</p><h3>个人批注</h3><textarea data-key="{sid}" placeholder="写下复核意见，自动保存在当前浏览器"></textarea><p class="muted">批注与固定机标结果分开保存。</p><details><summary>完整逐点证据链（{len(r['checks'])}条）</summary><div class="scroll"><table><tr>{''.join('<th>'+x+'</th>' for x in ['阶段','检查点','指标','状态','时间','证据ID','观察','影响','上下文','例外'])}</tr>{checks}</table></div></details><p><a href="{sid}/prediction.json">完整机标JSON</a></p></aside></section>''')
 (out/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))
 for name in ['selection.json','selection-policy.json','config.json','isolation-audit.json','runtime.json','timing.jsonl']:shutil.copyfile(d/name,out/name)
 shutil.copyfile(d/'rubric'/'active-expanded.json',out/'rubric-used.json');shutil.copyfile(d/'rubric'/'active-lock.json',out/'rubric-lock.json')
 header='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>构图 Rubric · 三条试跑</title><style>*{box-sizing:border-box}body{margin:0;height:100dvh;display:flex;flex-direction:column;font:15px/1.75 system-ui;color:#203746;background:#edf2f5}header{flex:none;background:#fff;border-bottom:1px solid #d7e1e7;padding:14px 24px}.topbar{display:flex;justify-content:space-between;gap:20px;align-items:center}h1{font-size:20px;margin:0}nav{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin-top:3px}a{color:#176681}button,select{font:inherit;border:1px solid #b8cbd5;border-radius:8px;padding:7px 12px;background:white;color:#234a60;cursor:pointer}button:hover:not(:disabled){background:#e9f3f6}button:disabled{opacity:.35;cursor:default}.pager{display:flex;gap:10px;align-items:center;flex:none}.counter{font-variant-numeric:tabular-nums;min-width:42px;text-align:center}.info{font-size:13px;color:#627682}.info summary{display:inline-block;padding:0;background:none;margin:0}.info p{max-width:1100px;margin:8px 0 0}.case{min-height:0;flex:1;display:grid;grid-template-columns:minmax(0,1.35fr) minmax(380px,1fr);gap:1px;background:#d7e1e7}.case[hidden]{display:none}.left-pane,.right-pane{overflow-y:auto;overscroll-behavior:contain;background:#fff;padding:22px 28px;min-width:0;min-height:0}.left-pane{background:#f8fafb}.right-pane{padding:24px 30px}h2{font-size:19px;margin:0 0 16px}h3{font-size:16px;margin:24px 0 8px;color:#31586c}video{display:block;width:100%;max-height:62vh;aspect-ratio:16/9;object-fit:contain;border-radius:10px;background:#111}img{max-width:100%}.muted{font-size:13px;color:#70828e;overflow-wrap:anywhere}.result-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.result-heading h2{margin:0}.grade{font-size:23px;font-weight:700;border-radius:10px;padding:5px 23px;background:#e9eff2}.grade-middle{background:#fff1ce;color:#8c6212}.grade-low{background:#fbe8e7;color:#a13a35}.grade-high{background:#dff4e9;color:#26734c}.conclusion{font-size:17px;line-height:1.9;margin-top:22px}details{margin:15px 0}summary{cursor:pointer;padding:11px 13px;background:#edf3f6;border-radius:7px;font-weight:550}details p,li{overflow-wrap:anywhere}table{border-collapse:collapse;min-width:1000px;font-size:13px}td,th{border:1px solid #ccd8df;padding:9px;vertical-align:top;min-width:100px}.scroll{overflow:auto;max-height:520px;margin-top:12px}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}figure{margin:8px 0}figcaption{font-size:12px;color:#70828e}textarea{width:100%;min-height:140px;padding:12px;border:1px solid #c5d4dc;border-radius:8px;font:inherit;resize:vertical}@media(max-width:850px){header{padding:12px 16px}.topbar{align-items:flex-start;flex-direction:column;gap:10px}.pager{align-self:flex-end}.case{grid-template-columns:minmax(0,1fr) minmax(300px,1fr)}.left-pane,.right-pane{padding:16px}h1{font-size:18px}}@media(max-width:650px){body{height:auto;min-height:100dvh}.case{display:block}.left-pane,.right-pane{overflow:visible}.gallery{grid-template-columns:1fr}video{max-height:none}.topbar{gap:8px}.pager{align-self:stretch;justify-content:flex-end}nav{font-size:13px}}</style><header><div class="topbar"><div><h1>构图 Rubric v2.1.1 · 三条试跑</h1><nav><a href="../../index.html">项目首页</a><a href="../../rubrics/composition_rubric_v2.html">完整 Rubric</a><button onclick="exportNotes()">导出批注</button></nav></div><div class="pager" aria-label="样本翻页"><button id="prev" aria-label="上一条样本">← 上一条</button><select id="case-select" aria-label="选择样本"><option value="0">T01</option><option value="1">T02</option><option value="2">T03</option></select><span class="counter" id="counter" aria-live="polite">1 / 3</span><button id="next" aria-label="下一条样本">下一条 →</button></div></div><details class="info"><summary>试跑与输入说明</summary><p>非原50条样本，由GPT-6.1 Sol按冻结Rubric判档，独立人工验证待完成。实际模型输入为80张160×90缩略帧及第20、60帧较大参考图；分割覆盖图按640×360排列。原始720p帧保留，但不能声称模型逐帧看到了720p细节。调用途径为本机Codex CLI；实际后端型号无法独立认证。未使用人工答案或旧机标；三条随机样本不保证覆盖高中低。</p></details></header>'''
 js='''<script>const cases=[...document.querySelectorAll('.case')],select=document.querySelector('#case-select'),prev=document.querySelector('#prev'),next=document.querySelector('#next');let current=0;function showCase(index){current=Math.max(0,Math.min(cases.length-1,index));cases.forEach((el,i)=>{el.hidden=i!==current;if(i!==current)el.querySelector('video').pause()});select.value=String(current);prev.disabled=current===0;next.disabled=current===cases.length-1;document.querySelector('#counter').textContent=(current+1)+' / '+cases.length;history.replaceState(null,'','#'+cases[current].id)}prev.onclick=()=>showCase(current-1);next.onclick=()=>showCase(current+1);select.onchange=()=>showCase(Number(select.value));window.addEventListener('hashchange',()=>{const i=cases.findIndex(el=>'#'+el.id===location.hash);if(i>=0)showCase(i)});document.addEventListener('keydown',ev=>{if(/INPUT|TEXTAREA|SELECT/.test(ev.target.tagName)||ev.target.isContentEditable)return;if(ev.key==='ArrowLeft'){ev.preventDefault();showCase(current-1)}if(ev.key==='ArrowRight'){ev.preventDefault();showCase(current+1)}});for(const el of document.querySelectorAll('textarea')){const k='rubric-v211-trial3-'+el.dataset.key;el.value=localStorage.getItem(k)||'';el.oninput=()=>localStorage.setItem(k,el.value)}function exportNotes(){const d={};document.querySelectorAll('textarea').forEach(x=>d[x.dataset.key]=x.value);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='trial3-notes.json';a.click();URL.revokeObjectURL(a.href)}showCase(Math.max(0,cases.findIndex(el=>'#'+el.id===location.hash)));</script></html>'''

 (out/'index.html').write_text(header+''.join(parts)+js);print(out/'index.html')
if __name__=='__main__':main()
